(()=>{'use strict';const items=new Set(),reduced=matchMedia('(prefers-reduced-motion:reduce)');let raf=0;function wake(){if(!raf&&!document.hidden)raf=requestAnimationFrame(tick)}function tick(t){raf=0;let running=false;for(const item of items)if(item.frame(t))running=true;if(running)wake()}class AcidPoster{constructor(element,options={}){if(element.acidPoster)return element.acidPoster;this.element=element;element.acidPoster=this;this.paused=!!options.paused;this.mini=element.classList.contains('acid-mini');this.visible=true;this.phase=Number(element.dataset.acidMode)*1.3;this.x=this.y=this.tx=this.ty=0;this.energy=0;this.dirty=true;this.flow=new MetalFlow(element.querySelector('.poster-sculpture'),Number(element.dataset.acidMode));this.listeners=[];this.io=new IntersectionObserver(entries=>{this.visible=entries[0].isIntersecting;this.last=0;this.dirty=true;wake()},{rootMargin:'40px'});this.io.observe(element);this.listen('pointermove',e=>{const r=element.getBoundingClientRect();this.tx=(e.clientX-r.left)/r.width*2-1;this.ty=(e.clientY-r.top)/r.height*2-1;this.dirty=true;wake()});this.listen('pointerleave',()=>{this.tx=this.ty=0;this.dirty=true;wake()});this.listen('pointerdown',()=>{this.energy=1;this.dirty=true;wake()});this.listen('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();this.energy=1;this.dirty=true;wake()}});this.setPaused(this.paused);items.add(this);wake()}listen(type,fn){this.element.addEventListener(type,fn);this.listeners.push([type,fn])}setPaused(p){this.paused=!!p;this.element.dataset.acidPaused=String(p);this.last=0;this.dirty=true;wake()}frame(stamp){if(!this.visible)return false;const moving=!this.paused&&!reduced.matches;const unsettled=Math.abs(this.tx-this.x)+Math.abs(this.ty-this.y)>.002||this.energy>.002;if(!moving&&!unsettled&&!this.dirty)return false;if(stamp-(this.drawn||0)<(this.mini?90:30))return true;const dt=this.last?Math.min(.15,(stamp-this.last)/1000):.033;this.last=this.drawn=stamp;if(moving)this.phase+=dt;this.x+=(this.tx-this.x)*.15;this.y+=(this.ty-this.y)*.15;this.energy*=.92;const st=this.element.style;st.setProperty('--acid-px',this.x.toFixed(3));st.setProperty('--acid-py',this.y.toFixed(3));st.setProperty('--acid-drift',Math.sin(this.phase*.4).toFixed(3));st.setProperty('--acid-turn',Math.cos(this.phase*.25).toFixed(3));st.setProperty('--acid-breathe',(1+Math.sin(this.phase*.5)*.009+this.energy*.018).toFixed(4));this.flow.draw(this.phase,this.x,this.y,this.energy);this.dirty=false;return moving||unsettled}destroy(){this.flow.destroy();this.io.disconnect();this.listeners.forEach(([type,fn])=>this.element.removeEventListener(type,fn));items.delete(this);delete this.element.acidPoster}static initAll(root=document){return [...root.querySelectorAll('.acid-poster')].map(el=>el.acidPoster||new AcidPoster(el))}}window.AcidPoster=AcidPoster;if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>AcidPoster.initAll());else AcidPoster.initAll();document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(raf);raf=0}else wake()});reduced.addEventListener('change',()=>{items.forEach(i=>i.dirty=true);wake()});})();
